#!/usr/bin/env python3
"""
Patch 15: popovers float above the whole app (macOS style) instead of being clipped
by the map, and a tiny stranded share reads '<0.1%'. Frontend only.

Run from the repository root with patches 05-14 applied. Every file replaced is
checked against the exact version this patch was written for; nothing is written
unless all of it matches. Safe to re-run.
"""
import hashlib, os, sys

def abort(msg):
    sys.exit(f"ABORT: {msg}. No files were written.")

if not os.path.isfile("frontend/src/map/shipGlyphs.js"):
    abort("run this from the slick-trace repository root, with patches 05-14 applied")
